    EstrategiaEntrega entrega = obterEstrategiaEntrega(req.modalidadeEntrega);
    EstrategiaCupom cupom = obterEstrategiaCupom(req.cupom);
    EstrategiaPagamento pagamento = obterEstrategiaPagamento(req.formaPagamento);

