    if (cupom != null) {
      desconto = cupom.calcularDesconto(req.itens, subtotal);
      freteGratis = cupom.aplicaFreteGratis();
    }
    desconto = rounding.round(desconto);

    double frete = 0.0;
    if (freteGratis || isClienteOuro(req.nivelClube)) {
