    req.modalidadeEntrega = modalidade;
    req.cupom = cupom;
    req.formaPagamento = forma;
    req.parcelas = parcelas;
    req.nivelClube = nivel;
    req.regiao = regiao;
    return req;
  }

  private Item criarItem(String nome, double preco, int qty, double peso) {
    Item item = new Item();
