1	package com.loja.checkout.service;
2	
3	import com.loja.checkout.model.CheckoutRequest;
4	import com.loja.checkout.model.CheckoutResponse;
5	import com.loja.checkout.model.ErrorResponse;
6	import com.loja.checkout.model.Item;
7	import com.loja.checkout.strategy.cupom.BemVindo10;
8	import com.loja.checkout.strategy.cupom.EstrategiaCupom;
9	import com.loja.checkout.strategy.cupom.FreteGratis;
10	import com.loja.checkout.strategy.cupom.Leve3Pague2;
11	import com.loja.checkout.strategy.cupom.Menos50;
12	import com.loja.checkout.strategy.entrega.EconomicaEntrega;
13	import com.loja.checkout.strategy.entrega.EstrategiaEntrega;
14	import com.loja.checkout.strategy.entrega.ExpressaEntrega;
15	import com.loja.checkout.strategy.entrega.MotoboyEntrega;
16	import com.loja.checkout.strategy.entrega.RetiradaLojaEntrega;
17	import com.loja.checkout.strategy.pagamento.BoletoPagamento;
18	import com.loja.checkout.strategy.pagamento.CartaoPagamento;
19	import com.loja.checkout.strategy.pagamento.EstrategiaPagamento;
20	import com.loja.checkout.strategy.pagamento.PixPagamento;
21	import java.util.HashMap;
22	import java.util.Map;
23	import org.springframework.stereotype.Service;
24	
25	@Service
26	public class CheckoutService {
27	  private RoundingService rounding;
28	
29	  public CheckoutService(RoundingService rounding) {
30	    this.rounding = rounding;
31	  }
32	
33	  public Object processar(CheckoutRequest req) {
34	    ErrorResponse erro = validar(req);
35	    if (erro != null) return erro;
36	
37	    EstrategiaEntrega entrega = obterEstrategiaEntrega(req.modalidadeEntrega);
38	    EstrategiaCupom cupom = obterEstrategiaCupom(req.cupom);
39	    EstrategiaPagamento pagamento = obterEstrategiaPagamento(req.formaPagamento);
40	
41	    double subtotal = calcularSubtotal(req.itens);
42	    double desconto = 0.0;
43	    boolean freteGratis = false;
44	    if (cupom != null) {
45	      desconto = cupom.calcularDesconto(req.itens, subtotal);
46	      freteGratis = cupom.aplicaFreteGratis();
47	    }
48	    desconto = rounding.round(desconto);
49	
50	    double frete = 0.0;
51	    if (freteGratis || isClienteOuro(req.nivelClube)) {
52	      frete = 0.0;
53	    } else {
54	      frete = entrega.calcularFrete(req.itens);
55	    }
56	    frete = rounding.round(frete);
57	
58	    double seguro = calcularSeguro(subtotal, req.regiao);
59	    seguro = rounding.round(seguro);
60	
61	    double totalPedido = rounding.round(subtotal - desconto + frete + seguro);
62	
63	    int parcelas = req.parcelas != null ? req.parcelas : 1;
64	    double ajuste = pagamento.calcularAjuste(totalPedido, parcelas);
65	    ajuste = rounding.round(ajuste);
66	
67	    double totalFinal = rounding.round(totalPedido + ajuste);
68	
69	    double valorParcela = 0.0;
70	    if (parcelas <= 3) {
71	      valorParcela = rounding.round(totalFinal / parcelas);
72	    } else {
73	      double taxaMensal = 0.0199;
74	      valorParcela = totalFinal * taxaMensal
75	          / (1 - Math.pow(1 + taxaMensal, -parcelas));
76	      valorParcela = rounding.round(valorParcela);
77	    }
78	
79	    double credito = calcularCredito(subtotal, req.nivelClube);
80	    credito = rounding.round(credito);
81	
82	    boolean brinde = isClienteOuro(req.nivelClube) && subtotal > 500.0;
83	
84	    CheckoutResponse resp = new CheckoutResponse();
85	    resp.subtotalProdutos = subtotal;
86	    resp.descontoCupom = desconto;
87	    resp.frete = frete;
88	    resp.prazoEntregaDias = entrega.prazoEntregaDias();
89	    resp.seguro = seguro;
90	    resp.ajustePagamento = ajuste;
91	    resp.totalFinal = totalFinal;
92	    resp.parcelas = parcelas;
93	    resp.valorParcela = valorParcela;
94	    resp.creditoProximaCompra = credito;
95	    resp.brinde = brinde;
96	
97	    return resp;
98	  }
99	
100	  private ErrorResponse validar(CheckoutRequest req) {
101	    if (req.itens == null || req.itens.isEmpty()) {
102	      return new ErrorResponse("PEDIDO_INVALIDO");
103	    }
104	
105	    for (Item item : req.itens) {
106	      if (item.precoUnitario <= 0 || item.quantidade <= 0 || item.pesoKg < 0) {
107	        return new ErrorResponse("PEDIDO_INVALIDO");
108	      }
109	    }
110	
111	    if (req.nivelClube == null || !validarNivelClube(req.nivelClube)) {
112	      return new ErrorResponse("NIVEL_CLUBE_INVALIDO");
113	    }
114	
115	    if (req.regiao == null || !validarRegiao(req.regiao)) {
116	      return new ErrorResponse("REGIAO_INVALIDA");
117	    }
118	
119	    if (req.modalidadeEntrega == null || !validarModalidade(req.modalidadeEntrega)) {
120	      return new ErrorResponse("MODALIDADE_INVALIDA");
121	    }
122	
123	    EstrategiaEntrega entrega = obterEstrategiaEntrega(req.modalidadeEntrega);
124	    if (!entrega.disponivel(req.itens)) {
125	      return new ErrorResponse("MODALIDADE_INDISPONIVEL");
126	    }
127	
128	    if (req.cupom != null && !validarCupom(req.cupom)) {
129	      return new ErrorResponse("CUPOM_INVALIDO");
130	    }
131	
132	    if (req.cupom != null) {
133	      EstrategiaCupom estrategiaCupom = obterEstrategiaCupom(req.cupom);
134	      double subtotal = calcularSubtotal(req.itens);
135	      if (!estrategiaCupom.aplicavel(req.itens, subtotal)) {
136	        return new ErrorResponse("CUPOM_NAO_APLICAVEL");
137	      }
138	    }
139	
140	    if (req.formaPagamento == null || !validarFormaPagamento(req.formaPagamento)) {
141	      return new ErrorResponse("FORMA_PAGAMENTO_INVALIDA");
142	    }
143	
144	    int parcelas = req.parcelas != null ? req.parcelas : 1;
145	    EstrategiaPagamento pagamento = obterEstrategiaPagamento(req.formaPagamento);
146	    if (!pagamento.parcelasValidas(parcelas)) {
147	      return new ErrorResponse("PARCELAMENTO_INVALIDO");
148	    }
149	
150	    double subtotalTemp = calcularSubtotal(req.itens);
151	    double descontoTemp = 0.0;
152	    if (req.cupom != null) {
153	      EstrategiaCupom cupom = obterEstrategiaCupom(req.cupom);
154	      descontoTemp = cupom.calcularDesconto(req.itens, subtotalTemp);
155	    }
156	    descontoTemp = rounding.round(descontoTemp);
157	
158	    double freteTemp = 0.0;
159	    if (req.cupom != null && obterEstrategiaCupom(req.cupom).aplicaFreteGratis()) {
160	      freteTemp = 0.0;
161	    } else if (!isClienteOuro(req.nivelClube)) {
162	      EstrategiaEntrega e = obterEstrategiaEntrega(req.modalidadeEntrega);
163	      freteTemp = e.calcularFrete(req.itens);
164	    }
165	    freteTemp = rounding.round(freteTemp);
166	
167	    double seguroTemp = calcularSeguro(subtotalTemp, req.regiao);
168	    seguroTemp = rounding.round(seguroTemp);
169	
170	    double totalTemp = rounding.round(subtotalTemp - descontoTemp + freteTemp + seguroTemp);
171	
172	    if (!pagamento.disponivel(totalTemp)) {
173	      return new ErrorResponse("FORMA_PAGAMENTO_INDISPONIVEL");
174	    }
175	
176	    return null;
177	  }
178	
179	  private boolean validarNivelClube(String nivel) {
180	    return nivel.equals("BRONZE") || nivel.equals("PRATA") || nivel.equals("OURO");
181	  }
182	
183	  private boolean validarRegiao(String regiao) {
184	    return regiao.equals("SUDESTE") || regiao.equals("SUL") || regiao.equals("CENTRO_OESTE")
185	        || regiao.equals("NORTE") || regiao.equals("NORDESTE");
186	  }
187	
188	  private boolean validarModalidade(String modalidade) {
189	    return modalidade.equals("ECONOMICA") || modalidade.equals("EXPRESSA")
190	        || modalidade.equals("RETIRADA_LOJA") || modalidade.equals("MOTOBOY");
191	  }
192	
193	  private boolean validarCupom(String cupom) {
194	    return cupom.equals("BEMVINDO10") || cupom.equals("MENOS50") || cupom.equals("FRETEGRATIS")
195	        || cupom.equals("LEVE3PAGUE2");
196	  }
197	
198	  private boolean validarFormaPagamento(String forma) {
199	    return forma.equals("PIX") || forma.equals("CARTAO") || forma.equals("BOLETO");
200	  }
201	
202	  private EstrategiaEntrega obterEstrategiaEntrega(String modalidade) {
203	    return switch (modalidade) {
204	      case "ECONOMICA" -> new EconomicaEntrega(rounding);
205	      case "EXPRESSA" -> new ExpressaEntrega(rounding);
206	      case "RETIRADA_LOJA" -> new RetiradaLojaEntrega();
207	      case "MOTOBOY" -> new MotoboyEntrega();
208	      default -> null;
209	    };
210	  }
211	
212	  private EstrategiaCupom obterEstrategiaCupom(String cupom) {
213	    if (cupom == null) return null;
214	    return switch (cupom) {
215	      case "BEMVINDO10" -> new BemVindo10(rounding);
216	      case "MENOS50" -> new Menos50();
217	      case "FRETEGRATIS" -> new FreteGratis();
218	      case "LEVE3PAGUE2" -> new Leve3Pague2(rounding);
219	      default -> null;
220	    };
221	  }
222	
223	  private EstrategiaPagamento obterEstrategiaPagamento(String forma) {
224	    return switch (forma) {
225	      case "PIX" -> new PixPagamento(rounding);
226	      case "CARTAO" -> new CartaoPagamento(rounding);
227	      case "BOLETO" -> new BoletoPagamento();
228	      default -> null;
229	    };
230	  }
231	
232	  private double calcularSubtotal(java.util.List<Item> itens) {
233	    double subtotal = 0.0;
234	    for (Item item : itens) {
235	      subtotal += item.precoUnitario * item.quantidade;
236	    }
237	    return rounding.round(subtotal);
238	  }
239	
240	  private double calcularSeguro(double subtotal, String regiao) {
241	    double percentual = switch (regiao) {
242	      case "SUDESTE" -> 0.01;
243	      case "SUL" -> 0.01;
244	      case "CENTRO_OESTE" -> 0.015;
245	      case "NORTE" -> 0.025;
246	      case "NORDESTE" -> 0.02;
247	      default -> 0.0;
248	    };
249	    return subtotal * percentual;
250	  }
251	
252	  private double calcularCredito(double subtotal, String nivelClube) {
253	    return switch (nivelClube) {
254	      case "BRONZE" -> 0.0;
255	      case "PRATA" -> subtotal * 0.02;
256	      case "OURO" -> subtotal * 0.05;
257	      default -> 0.0;
258	    };
259	  }
260	
261	  private boolean isClienteOuro(String nivelClube) {
262	    return "OURO".equals(nivelClube);
263	  }
264	}
